/* U3 LAN profile restoration: native IME provider, private persistence and
 * the existing type-0xcf frontend list. No network/session success is faked.
 */
#include <stdint.h>
#include <stddef.h>
#define MAGIC 0x504c3355u
#define VERSION 1u
#define LIMIT 8u
#define NAME_BYTES 64u
/* v4.93 split link (build_u3_pool_blob.py): EXT code goes to the second code segment rx2 (rw+0x4000, 0x20000
 * bytes), EXT_BSS data to the ext data segment rw2 (rx2+0x20000, 0x10000 bytes, zeroed at load). Calls and
 * data references across segments are plain PC-relative ones resolved by the linker. */
#define EXT __attribute__((section(".text.ext"),noinline))
#define EXT_BSS __attribute__((section(".bss.u3ext"),aligned(16)))

typedef struct { uint32_t magic,version,count,selected; char names[LIMIT][NAME_BYTES]; } ProfileFile;
typedef struct {
 uintptr_t init,status,result,term,open,read,write,close,rename;
 uint32_t initialized,phase,error,reserved;
 uint16_t text[16];
 ProfileFile profiles;
 uintptr_t show_page,lookup,loader,pool_init;
 uint32_t startup_phase,startup_error,startup_ticks,lobby_selected;
 uint32_t focus_done,focus_page,focus_moves,focus_busy;
 uint32_t k6_calls,k6_last,focus_tries,focus_fail;
 uint32_t lobby_error,reserved3;
 uint16_t ime_title[12];  /* IME title for the clan tag dialog (was padding) */
 uintptr_t profile_base;
 uintptr_t natives[64];  /* relocated native PS4 functions, see NATIVE_* */
} ProfileState;
#include "plat.h"   /* PLAN.md part A: the only door to the OS; prototypes, file wrappers, PLAT_DATA_DIR */
/* v4.93 ext data segment (rw2 = image 0x2088000 when state = 0x2064100). One object, so field offsets are
 * stable for runtime peeks: append new fields at the end only. */
typedef struct {
 char fmt[256];             /* +0x000 fmt() buffer (was state+0x2a00, which overlapped MedalList) */
 uint32_t coop[32];         /* +0x100 co-op debug: [0] lan-choice calls, [1] last ctx, [2] coop flag set, [3] spectate
                               ticks, [4] spoiler page opens, [5] 0x5e sends, [6] AI cycles, [7] spoiler source events,
                               [8] spoiler picks, [9] last picked class, [10] menu_back/close, [11] coop cams (f_360c28
                               coop branch), [12] last selected AI spawner id, [13] spectate list count, [14] fixed-camera steps (right/left),
                               [15] follow steps, [16] follow fallbacks (f_3638c8), [17] HUD draws (kind 19) */
 int32_t spoiler_sel[4];    /* +0x180 PS3 0x1233340[user]: LIST_SPOILER_CLASS selection (no PS4 storage) */
 uint8_t spoiler_toggle[4]; /* +0x190 PS3 0x1232ab0[user]: op 9 button 0xc toggle (no PS4 storage) */
 uint8_t pad0[0x6c];        /* +0x194 */
 uintptr_t net[16];         /* +0x200 libSceNet imports, filled by the builder's relocations (NET_IMPORTS, see NETF_*) */
 uint32_t lan[32];          /* +0x280 unused since agent B b010 (kept for the layout); was the LAN discovery (PS3 room browser slots 1/5): [0] state 0 closed / 1 open / 2 failed,
                               [1] socket, [2] own IPv4 (network order), [3] datagrams in, [4] requests answered,
                               [5] responses parsed, [6] rooms added, [7] broadcasts, [8] last error, [9] last broadcast
                               (net clock), [10]/[11] hosted room id lo/hi, [12] mode bits (bit0 = do not advertise),
                               [13] last sender IPv4 */
 uint8_t buf[0x800];        /* +0x300 datagram buffer */
 uint32_t stg[16];          /* +0xb00 v4.95 lobby stage guard (stage_guard): [0] watched stage sid, [1] watch start (net clock),
                               [2] frames watched, [3] fallbacks, [4] last failed sid, [5] last reason (1 level error 0xc,
                               2 timeout, 3 won't fit the loading heap), [6] free loading-heap pages at the last check,
                               [7] pages the stage package needs (0 until its header is read), [8] heap pages total,
                               [9] heap pages used, [10] heap peak pages, [11] map entries redirected, [12] gave up
                               (retail stage failed too), [13] fallback show pending, [14] last watched level state,
                               [15] guard ticks */
 uint32_t stg_bad[16];      /* +0xb40 stage sids that failed this session (map entries redirected away from them) */
 uint32_t taunt[16];        /* +0xb80 v4.95 taunt packs (taunt_tick): {list index+1, sid} for [0..1] user 0 equipped taunt,
                               [2..3] user 1, [4..5] PAGE_TAUNT hovered row; [8] list writes, [9] taunt sids without a
                               pack (disc taunts, served by anim-proto-multiplayer), [10] last such sid, [11] packs dropped
                               after a load error, [12..15] sids whose pack failed (state 0xc), never requested again */
 uint32_t room[32];         /* +0xbc0 unused since agent B b010 (kept for the layout); was the v4.98 LAN room (room_tick): [0] mode 0 idle / 1 hosting / 2 joining / 3 joined /
                               4 socket failed, [1] listen socket, [2] client socket, [3] own member id, [4] host member id,
                               [5] next member id, [6] messages in, [7] messages out, [8] last socket error, [9] joins
                               accepted, [10] members left, [11]/[12] room id lo/hi (PS3 f_924b54 form: hi = IPv4,
                               lo = TCP port << 16 | counter), [13] join start (net clock), [14] client rx fill,
                               [15]/[16] last party target handled lo/hi (0x17dd5d8), [17] mode bits (bit0: put remote
                               members into the host's match session at Create), [18] kicks, [19] last message id,
                               [20] room counter, [21] join message pending, [22] joins failed, [23] session fills */
 struct { char name[32]; uint32_t id,ip; uint8_t active,host,pad[2]; uint32_t len; uint8_t data[0x40]; int32_t fd; uint32_t rx; }
  rm[10];                   /* +0xc40 unused since b010: room members (slot 0 = this PC when hosting), 0x78 each */
 uint8_t rrx[10][0x100];    /* +0x10f0 unused since b010: host: per-member TCP receive buffers */
 uint8_t crx[0x500];        /* +0x1af0 unused since b010: client: TCP receive buffer */
 uint32_t lob[16];          /* +0x1ff0 v5.03 lobby scene levels (net_init_levels / stage_tick): [0] NetInit level steps,
                               [1] title levels unwanted (title-screen / sky-desert-teaser want entries removed),
                               [2] boot level list 0x1020810b count (-1 = symbol not found), [3..10] first 8 boot list
                               sids, [11] bit i = boot list entry i still in the level want list (at NetInit),
                               [12] stage want entries made visible (flags byte +0xe |= 3), [13] stage want flags byte
                               (0xff = not in the want list), [14] stage unwants at MP leave (PS3 f_28cb80),
                               [15] title-screen level state | sky-desert-teaser state << 8 (0xff = no slot) */
 uint32_t lob2[16];         /* +0x2030 v5.05 PS3 NetInit/NetShutdown boot list: [0] boot levels unwanted at NetInit,
                               [1] boot levels wanted again at LAN end, [2] mode bits (bit0 keep the boot levels wanted,
                               bit1 also unwant the actor package proto-sp like PS3 f_2901e0; default 0), [3] proto-sp
                               entries removed, [4] boot list unwanted this session (1/0) */
 uint32_t oob[16];          /* +0x2070 v5.07 out-of-bounds grid (PS3 VIS_CHEAT reader, vis_oob_tick): [0] checks, [1] grid
                               pointer low32 (0 = no VIS_CHEAT logged in), [2] last count of kill corners (8 = all), [3] timers
                               armed, [4] gate refusals (map without killvis sid / no map), [5..7] last test point x/y/z (float
                               bits), [8] skipped for a character state (0xb713a9fd/0x50b12ba3/0xc388fdab), [9] grid kills,
                               [10] last map killvis sid, [11] killvis sid kept at match start (U3MP_KILLVIS, 1/0), [12] all-ready
                               fade frames (f_2fd79c false or mgr+0x31e clear), [13..15] U3MP_OOB_TEST kill cell x/y/z (int, found
                               once per grid; 0x80000000 in [13] = grid has no kill voxel) */
 uint32_t oob2[16];         /* +0x20b0 v5.08: [0] grid low32 the U3MP_OOB_TEST cell was found in, [1] test-mode ticks */
 uint32_t fcam[16];         /* +0x20f0 v5.09 follow camera (PS3 f_3638c8, follow_update): [0] per-screen damage-fx updates
                               (vt+0x28 with 1.0), [1] last fx flag, [2] aims at a NetCharacter (0x685b80 = f_29a710 true),
                               [3] aims at a Player (screen camera locator), [4] aims skipped (target without character /
                               0x685b80 false / no camera manager), [5] skipped: debug camera byte 0x17d7b10 set, [6] skipped:
                               follow camera is not CameraControlFixed, [7] last fov (float bits), [8] other target types */
 uint32_t sw[32];           /* +0x2130 v5.09 MP sweep (item 8): [0] PAGE_PAUSE_MULTIPLAYER info source calls (enum 0xc2 =
                               PS3 0xc3 f_32f970), [1] map image answers, [2] map name texts, [3] game type texts,
                               [4] co-op difficulty texts, [5] no current map, [6] last-game title texts (enum 0x6e = PS3 f_32cf4c),
                               [7] last-game title without a netgame, [16..20] v5.10 match_stage_cleanup (see there) */
 uint64_t nbase;            /* +0x21b0 v5.13 image base for the script natives below (set by kind 44) */
 struct { uint64_t fn,cname; uint32_t csid,pad0; uint64_t sname; uint32_t ssid,pad1; uint64_t next; }
  nrec[2];                  /* +0x21b8 v5.13 script native records (PS4 static-ctor list 0x1b3b4b0 layout, 0x30 each) */
 uint32_t nat[8];           /* +0x2218 v5.13: [0] natives linked (kind 44 calls), [1] is-camera-underwater? calls,
                               [2] last result, [3] player-disable-zipline calls, [4] last player index, [5] events queued */
 uint32_t cd[8];            /* +0x2238 v5.13 Start Match countdown: [0] start presses, [1] popup start clock, [2] popup text,
                               [3] party session locked, [4] popups shown, [5] popup failed -> direct start, v5.14: [6] last
                               failed check (2 max, 3 min, 4 team; 0 passed), [7] size | type<<8 | min<<16 | max<<24 */
 char ptxt[2][88];          /* +0x2258 v5.14 PS3 front-end prompt texts ("|S| Options", "|T| Credits") */
 uint32_t pr[8];            /* +0x2308 v5.14 prompt source: [0] text calls, [1] button calls, [2] action calls, [3] PS3 answers,
                               [4] last page id, [5] last idx, v5.15: [6] count calls (kind 48), [7] last count answer */
 uint8_t melee[2][0x220];   /* +0x2328 v5.14 restored Shade melee moves (clones of PS4 0x1b90690 / 0x1b908b0) */
 uint32_t mel[4];           /* +0x2768 v5.14: [0] moves added, [1] list-1 count after, [2] list-6 count after, [3] refused (layout) */
 uint32_t pad2778[2];       /* +0x2778 */
 uint8_t melee16[2][0x220] __attribute__((aligned(16))); /* +0x2780 v5.15: the clones live here. Melee moves must be 16-byte
                               aligned (reset vt+0x48 = 0xb75200 does vmovaps [rdi+0x90]); melee[] above was 8 mod 16 and
                               crashed ResetActors (0xc98a5f -> 0xb7523d). melee[] is now unused. */
 uint32_t kr[16];           /* +0x2bc0 v5.16 kill-reward port (PS3 f_381ae4): [0] calls, [1] processed, [2] stat events,
                               [3] stat ring index, [4] history count, [5] deaths, [6] kills, [7] last flags, [8] last
                               killer id, [9] profile counter adds, [10] last victim id, [11] kill medal checks, [12] medal
                               checks, [13] PvP medal checks, [14] assists, [15] skipped (U3MP_KR=0) */
 uint32_t krs[16];          /* +0x2c00 last 16 stat event ids (ring, index kr[3]&15) */
 uint8_t krdummy[0x130];    /* +0x2c40 default player record (PS3 0x125ed48) for players missing from the table */
 uint32_t krp[8];           /* +0x2d70 v5.17 kill-reward points: [0] player score adds, [1] team score adds, [2] awards,
                               [3] awarded points total, [4] popup requests, [5] last popup value, [6] popups shown */
 uint32_t krb[4];           /* +0x2d90 v5.19 booster rewards: [0] booster queries, [1] ammo given, [2] grenades given,
                               [3] kickback meter adds */
 uint32_t ms[8];            /* +0x2da0 v5.23 mission-complete port (PS3 f_34b91c): [0] completions seen, [1] mission popups,
                               [2] booster level popups, [3] completion bits set, [4] last mission id, [5] cash awarded,
                               [6] skipped (already completed), [7] HUD queue full / text too long */
 uint32_t fe[4];            /* +0x2dc0 v5.25 U3MP_FORCE_END debug: [0] Playing (ns 0x1d) seen at clock, [1] 0 idle / 1 armed /
                               2 fired, [2] EndGame calls, [3] seconds configured */
 uint32_t sg[4];            /* +0x2dd0 v5.26 script-instance teardown 0x1257010 watch: [0] calls, [1] bad counts seen,
                               [2] last count, [3] bad count of the dump below (guarded when U3MP_SCRIPT_GUARD=1) */
 uint64_t sgd[64];          /* +0x2de0 dump of the first bad instance: [0] instance, [1..12] instance +0..+0x60,
                               [13..18] instance +0x640..+0x670, [19] object (+0x20), [20..31] object +0..+0x60,
                               [32] module (object +0x48), [33..46] module +0..+0x70, [47] guard applied, [48..63] spare */
 uint32_t hs[4];            /* +0x2fe0 v5.28 HUD-net slot 3 (spotted image): [0] slot calls, [1] draws, [2] last texture id,
                               [3] last icon index */
 uint32_t sc[8];            /* +0x2ff0 v5.30 solo-start port of the user's RPCS3 patches: [0] solo co-op ticks, [1] min-player
                               start checks skipped (U3MP_SOLO_COOP), [2] custom-game list entry counts preset, [3] co-op
                               level divide-by-zero guard hits (builder stub at 0x661ee5), [4] store-unlock flag 0->1
                               writes (U3MP_UNLOCK_STORE), [5] store flag value seen before the write, [6] debug byte
                               0x17d7a50+0x7d writes, [7] list preset done */
 uint64_t sgo[24];          /* +0x3010 v5.31 first bad teardown: owning script process (instance-0xb0, +0x00..+0xb8) when
                               called from a process dtor, else v5.32 state-script capture (see sg_capture_ss) */
 uint64_t ssb[4];           /* +0x30d0 v5.33 ss-survival group watch (U3MP_SS_WATCH): [0] current module base, [1] first base,
                               [2] base at the first change of group+0, [3] base before the last move */
 uint32_t ssw[16];          /* +0x30f0 [0] ticks with the module present, [1] base changes (incl. the first find), [2] group+0
                               at the first find, [3] group+0 now, [4] changed (1 = changed while watched, 2 = already bad at the first find), [5] old, [6] new, [7] net state at
                               the change, [8] relocate-skip counter (state+0x3db0) at the change, [9] net clock at the change,
                               [10] tick at the change, [11] module moves, [12] relocate-skip counter at the first find,
                               [13] net state at the first find, [14] group+0 right after the last move, [15] verify failures */
 uint32_t ssn[32];          /* +0x3130 group-0x40..+0x40 at the change (32 dwords) */
 uint32_t rb[8];            /* +0x31b0 v5.41 rank badge: [0] lookups [1] misses [2] hits [3] last value [4] party rows [5] profile box ops 4 [6] last name hash [7] lobby profile box retags (low 16) / party op-20 colour answers (high 16) */
 uint32_t r2[4];            /* +0x31d0 v5.43 R2 Change Team: calls, index substitutions, last op, last index */
 uint32_t cai[4];           /* +0x31e0 v5.43 co-op AI kill stats (kr_port): Npc victims, bit-48 skips (low 16) / marked Npcs spawned (high 16), stats emitted, last stat */
 uint32_t adv[8];           /* +0x31f0 v5.45 Advanced Settings (AdvRules: selection+1, respawn, health, weapon mode, flags, gt, weapon-table count, counters) */
 uintptr_t kimp[4];         /* +0x3210 v5.47 cinema kernel imports (U3MP_CINEMA=1 only): sceKernelMkdir, sceKernelGetdirentries (f002, was sceKernelGetdents), sceKernelUnlink, sceKernelStat */
 uint32_t cin[16];          /* +0x3230 v5.47 cinema: [0] init done, [1] prepare calls, [2] skipped (not ready), [3] mkdir results (last), [4] films found,
                               [5] files dropped (bad header), [6] slots freed, [7] last scan fd/err, [8] LIST_CINEMA calls, [9] last selected row */
 uint8_t cinbuf[0x800];     /* +0x3270 v5.47 cinema: getdents buffer */
 uint32_t fsw[4];           /* +0x3a70 v5.47 FUNCTIONS switch word, set by the builder: [0] bit0 U3MP_ADV=0, bit1 U3MP_CINEMA=1, bit2 U3MP_LOBBY_Q11=1,
                               bit3 U3MP_PLAYER_NET_ANIMS=0 (f004) */
 uint32_t nd[40];           /* +0x3a80 f001 net-clock diagnostic (nd_tick): net game process state ring + abort-flag edge snapshot;
                               f002: [32] EstablishConnection Enter kicks, [33] Enter runs, [34] last start time stamped */
 uint32_t dth[64];          /* +0x3b20 f003 NetEventPlayerDeath anim check (death_anim_check, kind 56 at the ctor 0x6ba9d0):
                               [0] ctor calls, [1] anim sid not in the player's tables, [2] last missing sid, [3] character type
                               sid, [4] caller return address - base, [5] net player id, [6] sends skipped (U3MP_DEATH_GUARD),
                               [7] last sid looked up, [8] tables present (bit i), [9] damage type (param+0x1c, from 0x99cce0 only),
                               [10] attacker type sid (+0x30), [11] attacker +0x28, [12] calls from 0x99cce0, [13] found count,
                               [14] last found table index, [15] last found anim index, [16..31] damage info +0x00..+0x3c,
                               [32..39] attacker +0x20..+0x3c, [40..47] each table's anim count,
                               [48..51] the net player's position np+0x00..+0x0c (float bits), [52..63] damage info +0x40..+0x6c */
 uint64_t dthr[2];          /* +0x3c20 r13 (damage info) / r14 (death state) at the 0x99ccdb call, stored by the call-site stub */
 uint32_t pna[8];           /* +0x3c30 f004 Player net anim tables (player_net_anims, kind 57 at 0xbd7764): [0] Player inits in MP, [1] tables
                               found (sum), [2] last init: bit i = table i found, [3] runs skipped (array missing), [4] switch off */
 /* v5.65: one reserved block per parallel FUNCTIONS agent (so their merges never collide). [0..3] = switch words set by the
  * builder (image[rw2+0x3c50/0x4050/0x4450 + 4*i]), [4..255] = that agent's diagnostics. Bigger data: own EXT_BSS statics. */
 uint32_t ea[256];          /* +0x3c50 agent A (emblem / profile / UI items); a022: ea[116] shimmer-B substitutions,
                               ea[117] last substituted B (float bits), written by the asm stub at x-stub 0x14000 */
 uint32_t eb[256];          /* +0x4050 agent B (cinema) */
 uint32_t ec[256];          /* +0x4450 agent C (gameplay functions + remaining shortcuts) */
} ExtState;
