  if(*(uint32_t*)(item+0x34)==0xcf&&*(uint32_t*)(item+0x40)==tag)continue;
  if(*(uint32_t*)(item+0x34)!=original||*(uint32_t*)(item+0x40)!=0)return 0;
  *(uint32_t*)(item+0x34)=0xcf;*(uint32_t*)(item+0x40)=tag;
