  uint8_t *page=pages+i*0x80;uint32_t id=*(uint32_t*)(page+8);
  if(id==0x53cbb5f2){ok=retag_page(page,4,0);retag_lobby_box(page,keep_box&1);}
  else if(id==0xb99a3235)retag_page(page,9,keep_box);
  else if(id==0x735c4dbe)retag_page(page,1,0); /* PAGE_MULTIPLAYER_CINEMA_LIST */
  else if(id==0xca9509a0u)retag_cinema_page(page);   /* agent B b002: PAGE_CINEMA, hidden MPEG / Protect / Unprotect */
  else retag_party(page);
