static int mp_write_all(ProfileState *s,int fd,const uint8_t *p,size_t n){
 while(n){int64_t w=plat_write(s,fd,p,n);if(w<=0||(uint64_t)w>n)return 0;p+=w;n-=(size_t)w;}
 return 1;
}
static int mp_read_all(ProfileState *s,int fd,uint8_t *p,size_t n){
 while(n){int64_t r=plat_read(s,fd,p,n);if(r<=0||(uint64_t)r>n)return 0;p+=r;n-=(size_t)r;}
 return 1;
}
