static int stage_unwant(uintptr_t base,uint32_t sid){
 int n=0;
 for(int li=0;li<2;li++){
  uint32_t *cnt=(uint32_t*)(base+0x1afcf10+(li?0x38:0x28));uint8_t *a=*(uint8_t**)(base+0x1afcf10+(li?0x40:0x30));
  if(!stage_ptr_ok(a)||*cnt>4096)continue;
  for(uint32_t i=0;i<*cnt;){
   if(*(uint32_t*)(a+(size_t)i*0x18+8)==sid){for(uint32_t j=i;j+1<*cnt;j++)for(int k=0;k<0x18;k++)a[(size_t)j*0x18+k]=a[(size_t)(j+1)*0x18+k];(*cnt)--;n++;}
   else i++;}}
 return n;}
static int stage_wanted(uintptr_t base,uint32_t sid){
 for(int li=0;li<2;li++){
  uint32_t cnt=*(uint32_t*)(base+0x1afcf10+(li?0x38:0x28));uint8_t *a=*(uint8_t**)(base+0x1afcf10+(li?0x40:0x30));
  if(!stage_ptr_ok(a)||cnt>4096)continue;
  for(uint32_t i=0;i<cnt;i++)if(*(uint32_t*)(a+(size_t)i*0x18+8)==sid)return 1;}
 return 0;}
