  for(int i=0;i<6;i++)X.sgd[13+i]=*(uint64_t*)(in+0x640+i*8);
  uint64_t ob=*(uint64_t*)(in+0x20);X.sgd[19]=ob;
  if(sg_ptr(ob)){for(int i=0;i<12;i++)X.sgd[20+i]=*(uint64_t*)(ob+i*8);
   uint64_t md=*(uint64_t*)(ob+0x48);X.sgd[32]=md;
   if(sg_ptr(md))for(int i=0;i<14;i++)X.sgd[33+i]=*(uint64_t*)(md+i*8);}
