static int ol_load_token(ProfileState *s,uint32_t slot){
 char p[PLAT_PATH(40)];ol_path(p,slot,0);OL.token[0]=0;OL.player=0;
 int64_t fd=plat_open(s,p,0,0);if(fd<0)return 0;
 OnlineFile f;clear(&f,sizeof(f));int ok=mp_read_all(s,(int)fd,(uint8_t*)&f,sizeof(f));plat_close(s,(int)fd);
 if(!ok||f.magic!=OL_MAGIC||f.version!=OL_VERSION||f.sum!=ol_sum(&f))return 0;
 if(!ol_streq(f.server,OL.server,sizeof(f.server))||!ol_streq(f.name,OL.name,NAME_BYTES))return 0;   /* another server / name */
 ol_strcpy(OL.token,f.token,sizeof(OL.token));OL.player=f.player;return 1;}
static int ol_save_token(ProfileState *s){
 OnlineFile f;clear(&f,sizeof(f));f.magic=OL_MAGIC;f.version=OL_VERSION;
 ol_strcpy(f.server,OL.server,sizeof(f.server));ol_strcpy(f.name,OL.name,NAME_BYTES);ol_strcpy(f.token,OL.token,sizeof(f.token));
 f.player=OL.player;f.sum=ol_sum(&f);
 char path_[PLAT_PATH(40)],tmp_[PLAT_PATH(40)];ol_path(path_,OL.slot,0);ol_path(tmp_,OL.slot,1);
 for(int attempt=0;attempt<2;attempt++){   /* temp + rename, then in place (as mp_write) */
  const char *target=attempt?path_:tmp_;
  int64_t fd=plat_open(s,target,0x601,0600);
  if(fd<0)continue;
  int ok=mp_write_all(s,(int)fd,(const uint8_t*)&f,sizeof(f));
  if(plat_close(s,(int)fd)<0)ok=0;
  if(!ok)continue;
  if(attempt||plat_rename(s,tmp_,path_)==0){X.eb[52]++;return 1;}}
 return 0;}
