 if(OL.fd>0&&X.net[NETF_CLOSE])((int32_t(*)(int))X.net[NETF_CLOSE])(OL.fd);
 OL.fd=0;OL.rx_len=OL.tx_len=0;OL.party=0;OL.pcount=0;OL.st=st;
