 char name[0x24];clear(name,sizeof(name));for(int i=0;i<16&&d[34+i];i++)name[i]=(char)d[34+i];
 if(cmd>6||!name[0]||!lnb_strcmp(name,m->me)){m->pl_sig_bad++;return;}
 int32_t now=loc_now(base);PlPeer *p=pl_find(m,name);
 if(!p){if(cmd!=2)return;p=pl_new(m,name);if(!p)return;p->src=1;p->t_first=now|1;}   /* the other side reached us first: take its address */
 if(p->st==PL_CLOSING){if(cmd==6)p->st=PL_FREE;return;}
 if(p->ip!=ip||p->port!=port){p->ip=ip;p->port=port;if(p->st==PL_ACTIVE)pl_fill(base,p->name,ip,port,1);m->pl_dirty=1;}
 p->rx++;p->cmds[cmd]++;p->t_rx=now;
 if(p->st!=PL_CONNECT&&p->st!=PL_ACTIVE){   /* lookup still running / failed / lost: the peer knows us, so connect from here */
  if(cmd==5){pl_sig(m,p,6,0,0);return;}
  p->st=PL_CONNECT;p->t0=now;p->cstamp=pl_us(base);p->t_send=now;p->t_retry=0;pl_sig(m,p,2,p->cstamp,0);m->pl_dirty=1;}
