 int32_t now=loc_now(base);if(now==m->pl_now)return;m->pl_now=now;
 int ready=rc_state==RC_READY&&rc_running;
 if(m->uid&&m->rpcn_ip&&(!m->probe_at||now-m->probe_at>=0)){
  m->probe_at=now+(m->pub_ok?20:5)*OL_TICKS_S;if(!m->probe_at)m->probe_at=1;
  uint8_t q[16];clear(q,16);q[0]=1;copy(q+1,&m->uid,8);copy(q+9,&m->lip,4);
  if(gt_sendto(&pl_sock,q,13,m->rpcn_ip,3657)>0){m->probe_tx++;m->pl_dirty=1;}}
