 if(!err){
  if(n==6){ip=*(const uint32_t*)d;port=*(const uint16_t*)(d+4);}
  else if(n>=8&&rc_le32(d)==n-4){   /* the handoff's length-prefixed form: {1: bytes ip} {2: {1: varint port}} */
   const uint8_t *q=d+4,*e=d+n;
   while(q<e){uint32_t tag=*q++;if(q>=e)break;uint32_t l=*q++;if(q+l>e)break;
    if(tag==10&&l==4)copy(&ip,q,4);
    else if(tag==18&&l>=2&&q[0]==8){uint32_t v=0,sh=0;for(uint32_t i=1;i<l&&sh<28;i++){v|=(uint32_t)(q[i]&127)<<sh;sh+=7;if(!(q[i]&128))break;}port=v;}
    q+=l;}}}
