 static const char t_i[]="invite to ",t_k[]=" (key ",t_0[]="): stored on the invite-server",t_1[]="): invite-server unreachable earlier",
  t_2[]="): invite-server not reachable",t_3[]="): invite-server gave no valid reply",t_4[]="): invite-server answered without '+' (first byte ",
  t_m[]=", sent inside an RPCN message";
 char b[200];int n=0;so_c_(b,&n,so_pfx);so_c_(b,&n,t_i);so_cn(b,&n,to,16);so_c_(b,&n,t_k);so_cx(b,&n,*(const uint32_t*)blob);
