 if(pl>RC_RATE){uint64_t k[25];clear(k,sizeof(k));uint32_t at=0;rc_absorb(k,(const uint8_t*)pw,pl,&at);rc_final(k,at,key);}else for(uint32_t i=0;i<pl;i++)key[i]=(uint8_t)pw[i];
